sub walk { my ($d)=@_; opendir(my $h,$d) or return; while(defined(my $e=readdir $h)){ next if $e eq '.'||$e eq '..'||$e eq '.git'||$e eq 'node_modules'; my $p="$d/$e"; if(-d $p){walk($p)} elsif($p=~/\.go$/){push @files,$p} } closedir $h }
sub clean { my($s)=@_; $s =~ s{"(?:\\.|[^"\\])*"}{""}gs; $s =~ s{`[^`]*`}{``}gs; $s =~ s{'(?:\\.|[^'\\])*'}{''}gs; $s =~ s{//[^\n]*}{}g; $s =~ s{/\*.*?\*/}{}gs; return $s }
walk('.'); my (%calls,@decl);
for my $f (@files){ open(my $h,'<',$f) or next; local $/=undef; my $raw=<$h>; close $h; my $s=clean($raw); while($s =~ /\b([A-Za-z_]\w*)\s*(?:\[[^\]\n]*\]\s*)?\(/g){$calls{$1}++} next unless $f =~ m{^\./internal/}; my $line=1; for my $l (split /\n/,$s,-1){ if($l =~ /^\s*func\s+(?:\([^)]*\)\s*)?([A-Za-z_]\w*)\s*(?:\[[^]]*\]\s*)?\(/){ push @decl,[$calls{$1}//0,$1,$f,$line,$l] } $line++ }}
@decl=sort{$b->[0]<=>$a->[0]||$a->[1]cmp$b->[1]}@decl; for my $d (@decl[0..($#decl<59?$#decl:59)]){printf "%5d  %-35s %s:%d  %s\n",@$d[0..3],$d->[4]}
print "FILES ".scalar(@files)." DECLS ".scalar(@decl)."\n";
PERL

